Run this setup command in one bash call:

set -eu
root=/mnt/session/glob65
rm -rf "$root"
mkdir -p "$root/nested/deeper" "$root/node_modules/pkg"
printf 'alpha' > "$root/a.md"
printf 'zulu' > "$root/z.md"
printf 'hidden' > "$root/.hidden.md"
printf 'nested' > "$root/nested/b.md"
printf 'deep' > "$root/nested/deeper/c.md"
printf 'ignored' > "$root/ignored.md"
printf 'dependency' > "$root/node_modules/pkg/dependency.md"
printf 'ignored.md
' > "$root/.gitignore"
i=1
while [ "$i" -le 150 ]; do printf x > "$root/many-$(printf '%03d' "$i").txt"; i=$((i+1)); done


Then make these glob calls exactly in order:
1. {"pattern":"*.md"}
2. {"pattern":"*.nomatch","path":"/mnt/session/glob65"}
3. {"pattern":"*.md","path":"/mnt/session/glob65/missing"}
4. {"pattern":"**/*.md","path":"/mnt/session/glob65"}
5. {"pattern":"*.md","path":"/mnt/session/glob65"}
6. {"pattern":".*","path":"/mnt/session/glob65"}
7. {"pattern":"many-*.txt","path":"/mnt/session/glob65"}
8. {"pattern":"[","path":"/mnt/session/glob65"}
